def critical_path(acts, order):
    # acts[a] = (기간, 선행 목록), order: 위상 정렬 순
    es, ef = {}, {}
    for a in order:  # 전진 계산
        es[a] = max((ef[p] for p in acts[a][1]), default=0)
        ef[a] = es[a] + acts[a][0]
    T = max(ef.values())  # 프로젝트 최소 완료시간
    succ = {a: [] for a in acts}
    for a in acts:
        for p in acts[a][1]:
            succ[p].append(a)
    ls, lf = {}, {}
    for a in reversed(order):  # 후진 계산
        lf[a] = min((ls[s] for s in succ[a]), default=T)
        ls[a] = lf[a] - acts[a][0]
    # 총여유 TF = LS - ES = 0 인 활동이 주공정
    cp = [a for a in order if ls[a] - es[a] == 0]
    return T, cp

critical-path-method.pseudocode:
def cpm(tasks, dur, preds):
    # tasks는 위상 순서로 정렬되어 있다고 가정
    es, ef = {}, {}
    for t in tasks:  # 전진 계산
        es[t] = max((ef[p] for p in preds[t]), default=0)
        ef[t] = es[t] + dur[t]
    finish = max(ef.values())  # 최소 완료 기간
    succs = {t: [] for t in tasks}
    for t in tasks:
        for p in preds[t]:
            succs[p].append(t)
    ls, lf = {}, {}
    for t in reversed(tasks):  # 후진 계산
        lf[t] = min((ls[s] for s in succs[t]),
                    default=finish)
        ls[t] = lf[t] - dur[t]
    # 총여유(TF) = LS - ES, 0이면 주공정
    critical = [t for t in tasks if ls[t] == es[t]]
    return finish, critical

