def html_escape(s):
    table = {'&': '&amp;', '<': '&lt;', '>': '&gt;',
             '"': '&quot;', "'": '&#x27;'}
    return ''.join(table.get(ch, ch) for ch in s)

def render_comment(comment):
    # 저장된 입력을 출력 시점에 HTML 문맥으로 인코딩
    return '<p>' + html_escape(comment) + '</p>'

